INSERT IGNORE INTO `servicio` (`idServicio`,`idCategoria_servicio`,`nombre_servicio`,`descripcion_servicio`,`operador_alta`,`fechaAlta`,`descripcion_corta`,`observaciones`,`documentacionViajero`,`cancelaciones`,`idPrestador`,`idTextoMiniaturas`,`orden`,`habilitado`,`idOrigen`,`idDestino`,`destacado`,`nombre_servicio_en`,`nombre_servicio_pt`,`nombre_servicio_it`,`descripcion_servicio_en`,`descripcion_servicio_pt`,`descripcion_servicio_it`,`descripcion_corta_en`,`descripcion_corta_pt`,`descripcion_corta_it`,`observaciones_en`,`observaciones_pt`,`observaciones_it`,`documentacionViajero_en`,`documentacionViajero_pt`,`documentacionViajero_it`) VALUES ('734','4','Rosario → Florianópolis','<p data-start=\"3272\" data-end=\"3539\"><br data-start=\"3407\" data-end=\"3410\">Es una de las ciudades brasileñas con mayor influencia europea del país, no solo culturalmente, sino también en términos climáticos.</p>
<p data-start=\"3541\" data-end=\"3811\">Situada en la Isla de Santa Catarina, en el sur del país, Florianópolis vive del turismo sudamericano y, como toda ciudad brasileña, posee playas que no tienen nada que envidiar a las de sus vecinas del norte, aunque las temperaturas de invierno limitan el baño de mar durante todo el año.</p>
<p data-start=\"3813\" data-end=\"4001\">Florianópolis, también conocida como la “Isla de la Magia”, es uno de los destinos más emblemáticos del sur de Brasil. Combina playas paradisíacas, naturaleza exuberante y una vida urbana vibrante.</p>
<p data-start=\"4003\" data-end=\"4130\">Playas para todos los gustos: desde las tranquilas como Jurerê Internacional hasta las más salvajes como Praia Mole o Campeche.</p>
<p data-start=\"4132\" data-end=\"4229\">Paseos icónicos como la Isla do Campeche, la Costa da Lagoa o el Barco Pirata en Canasvieiras.</p>
<p data-start=\"4231\" data-end=\"4315\">Gastronomía local basada en frutos de mar frescos y sabores típicos catarinenses.</p>
<p data-start=\"4317\" data-end=\"4386\">Vida nocturna animada y segura, con bares y beach clubs junto al mar.</p>
<p data-start=\"4388\" data-end=\"4462\"> Ideal para: familias, parejas, grupos de amigos y amantes de la naturaleza.</p>
<p data-start=\"4618\" data-end=\"4736\"> </p>
','1','2021-10-19 19:50:50.734817','<p>Florianópolis es conocida como la Isla de la Magia debido a la fuerte presencia de alquimistas durante la colonización española y portuguesa.</p>
','<p data-start=\"4464\" data-end=\"4616\"><strong data-start=\"4464\" data-end=\"4488\">Condición de menores:</strong> hasta 2 años sin costo y sin servicio. Pagan solo asistencia médica de USD 25 neto. A partir de los 3 años, paga como adulto.</p>
<p data-start=\"4618\" data-end=\"4736\"><strong data-start=\"4618\" data-end=\"4673\">Tarifa por persona en base doble expresada en dólares</strong>, sujeta a modificación sin previo aviso al momento de la reserva.</p>
','<p>Pasaporte y DNI.</p>','0','0','37',NULL,'1','33','32','1','Rosario →  Florianópolis','Rosario →  Florianópolis','Rosario →  Florianópolis','<p data-start=\"2037\" data-end=\"2295\">Located on Santa Catarina Island in the south of the country, Florianópolis thrives on South American tourism and, like every Brazilian city, offers beaches that rival those of its northern neighbors, although winter temperatures limit swimming year-round.</p>
<p data-start=\"2297\" data-end=\"2499\">Florianópolis, also known as the “Ilha da Magia” (Island of Magic), is one of the most iconic destinations in southern Brazil. It combines paradise beaches, lush nature, and a vibrant urban lifestyle.</p>
<p data-start=\"2501\" data-end=\"2615\">Beaches for all tastes: from peaceful ones like Jurerê Internacional to wilder ones like Praia Mole or Campeche.</p>
<p data-start=\"2617\" data-end=\"2708\">Iconic tours such as Campeche Island, Costa da Lagoa, or the Pirate Ship in Canasvieiras.</p>
<p data-start=\"2710\" data-end=\"2789\">Local cuisine based on fresh seafood and typical flavors from Santa Catarina.</p>
<p data-start=\"2791\" data-end=\"2860\">Lively and safe nightlife with bars and beach clubs facing the sea.</p>
<p data-start=\"2862\" data-end=\"2934\">Ideal for: families, couples, groups of friends, and nature lovers.</p>','<p data-start=\"3272\" data-end=\"3539\"><br data-start=\"3407\" data-end=\"3410\">É uma das cidades brasileiras com maior influência europeia do país, não apenas culturalmente, mas também em termos climáticos.</p>
<p data-start=\"3541\" data-end=\"3811\">Situada na Ilha de Santa Catarina, no sul do país, Florianópolis vive do turismo sul-americano e, como toda cidade brasileira, possui praias que não ficam atrás das de suas vizinhas do norte, embora as temperaturas de inverno limitem o banho de mar durante todo o ano.</p>
<p data-start=\"3813\" data-end=\"4001\">Florianópolis, também conhecida como a “Ilha da Magia”, é um dos destinos mais emblemáticos do sul do Brasil. Combina praias paradisíacas, natureza exuberante e uma vida urbana vibrante.</p>
<p data-start=\"4003\" data-end=\"4130\">Praias para todos os gostos: desde as tranquilas como Jurerê Internacional até as mais selvagens como Praia Mole ou Campeche.</p>
<p data-start=\"4132\" data-end=\"4229\">Passeios icônicos, como a Ilha do Campeche, a Costa da Lagoa ou o Barco Pirata em Canasvieiras.</p>
<p data-start=\"4231\" data-end=\"4315\">Gastronomia local baseada em frutos do mar frescos e sabores típicos catarinenses.</p>
<p data-start=\"4317\" data-end=\"4386\">Vida noturna animada e segura, com bares e beach clubs à beira-mar.</p>
<p data-start=\"4388\" data-end=\"4462\">Ideal para: famílias, casais, grupos de amigos e amantes da natureza.</p>
<p data-start=\"4618\" data-end=\"4736\"> </p>','<p data-start=\"4765\" data-end=\"5022\">È una delle città brasiliane con la maggiore influenza europea, non solo a livello culturale ma anche climatico.</p>
<p data-start=\"5024\" data-end=\"5295\">Situata sull’isola di Santa Catarina, nel sud del Paese, Florianópolis vive di turismo sudamericano e, come ogni città brasiliana, offre spiagge che non hanno nulla da invidiare a quelle del nord, anche se le temperature invernali limitano i bagni durante tutto l’anno.</p>
<p data-start=\"5297\" data-end=\"5489\">Florianópolis, conosciuta anche come “Ilha da Magia”, è una delle destinazioni più emblematiche del sud del Brasile. Combina spiagge paradisiache, natura rigogliosa e una vivace vita urbana.</p>
<p data-start=\"5491\" data-end=\"5616\">Spiagge per tutti i gusti: da quelle tranquille come Jurerê Internacional a quelle più selvagge come Praia Mole o Campeche.</p>
<p data-start=\"5618\" data-end=\"5720\">Escursioni iconiche come l’Isola di Campeche, la Costa da Lagoa o la Nave dei Pirati a Canasvieiras.</p>
<p data-start=\"5722\" data-end=\"5795\">Cucina locale a base di pesce fresco e sapori tipici di Santa Catarina.</p>
<p data-start=\"5797\" data-end=\"5863\">Vita notturna vivace e sicura, con bar e beach club fronte mare.</p>
<p data-start=\"5865\" data-end=\"5938\">Ideale per: famiglie, coppie, gruppi di amici e amanti della natura.</p>','<p>Florianópolis is known as the Island of Magic due to the strong presence of alchemists during the Spanish and Portuguese colonization. It is one of the Brazilian cities with the most European influence, not only culturally but also in terms of climate.</p>','<p>Florianópolis é conhecida como a Ilha da Magia devido à forte presença de alquimistas durante a colonização espanhola e portuguesa.</p>','<p>Florianópolis è conosciuta come l’Isola della Magia per la forte presenza di alchimisti durante la colonizzazione spagnola e portoghese.</p>','<p data-start=\"2936\" data-end=\"3108\"><strong data-start=\"2936\" data-end=\"2956\">Children policy:</strong> up to 2 years old free of charge, no services included. Only medical assistance fee of USD 25 net applies. From 3 years old, full adult rate applies.</p>
<p data-start=\"3110\" data-end=\"3242\"><strong data-start=\"3110\" data-end=\"3176\">Rate per person in double occupancy, expressed in U.S. dollars</strong>, subject to change without prior notice at the time of booking.</p>','<p data-start=\"4464\" data-end=\"4616\"><strong data-start=\"4464\" data-end=\"4488\">Condição de menores:</strong> até 2 anos sem custo e sem serviço. Pagam apenas assistência médica de USD 25 líquido. A partir dos 3 anos, paga como adulto.</p>
<p data-start=\"4618\" data-end=\"4736\"><strong data-start=\"4618\" data-end=\"4673\">Tarifa por pessoa em base dupla expressa em dólares</strong>, sujeita a alteração sem aviso prévio no momento da reserva.</p>','<p data-start=\"5940\" data-end=\"6098\"><strong data-start=\"5940\" data-end=\"5969\">Condizioni per i bambini:</strong> fino a 2 anni gratis e senza servizio. Si paga solo l’assistenza medica di USD 25 netti. Dai 3 anni in su si paga come adulto.</p>
<p data-start=\"6100\" data-end=\"6231\"><strong data-start=\"6100\" data-end=\"6160\">Tariffa per persona in camera doppia espressa in dollari</strong>, soggetta a modifiche senza preavviso al momento della prenotazione.</p>','<p data-start=\"2936\" data-end=\"3108\">Passport and ID</p>','<p>Passaporte e RG.</p>','<p>Passaportte e Carta de Identtita</p>');
INSERT IGNORE INTO `servicio` (`idServicio`,`idCategoria_servicio`,`nombre_servicio`,`descripcion_servicio`,`operador_alta`,`fechaAlta`,`descripcion_corta`,`observaciones`,`documentacionViajero`,`cancelaciones`,`idPrestador`,`idTextoMiniaturas`,`orden`,`habilitado`,`idOrigen`,`idDestino`,`destacado`,`nombre_servicio_en`,`nombre_servicio_pt`,`nombre_servicio_it`,`descripcion_servicio_en`,`descripcion_servicio_pt`,`descripcion_servicio_it`,`descripcion_corta_en`,`descripcion_corta_pt`,`descripcion_corta_it`,`observaciones_en`,`observaciones_pt`,`observaciones_it`,`documentacionViajero_en`,`documentacionViajero_pt`,`documentacionViajero_it`) VALUES ('735','4','Córdoba → Balneário Camboriú','<p data-start=\"3325\" data-end=\"3542\">Balneário Camboriú es uno de los destinos más buscados del sur de Brasil. Con fuerte influencia europea e infraestructura turística moderna, combina playas, gastronomía, paseos y diversión en un ambiente urbano vibrante.</p>
<p data-start=\"3544\" data-end=\"3719\">Las playas se adaptan a todos los estilos: desde la concurrida Praia Central hasta rincones tranquilos como Estaleirinho o Laranjeiras, accesible por el teleférico del Parque Unipraias.</p>
<p data-start=\"3721\" data-end=\"3942\">Entre los destaques se encuentran el Barco Pirata, el Cristo Luz, el Museo del Automóvil y diversos miradores naturales. La gastronomía mezcla sabores internacionales con pescados y mariscos frescos. La vida nocturna también es un gran atractivo.</p>
<p data-start=\"3944\" data-end=\"4035\">Ideal para familias, parejas y grupos de amigos que buscan playa, confort y entretenimiento.</p>
<hr data-start=\"4037\" data-end=\"4040\">
<h3 data-start=\"4042\" data-end=\"4076\"><strong data-start=\"4046\" data-end=\"4076\">Descripción General del Servicio</strong></h3>
<p data-start=\"4077\" data-end=\"4290\">Nuestros servicios parten de Córdoba en ómnibus de turismo rumbo a Camboriú, Florianópolis o Torres. Los ómnibus son confortables, climatizados, con butacas reclinables y acompañamiento durante todo el viaje en grupo.</p>
<p data-start=\"4292\" data-end=\"4548\">El trayecto incluye puntos de embarque a lo largo de la ruta, permitiendo que los pasajeros suban en diferentes ciudades. Ya en Brasil, la llegada se realiza directamente en los hoteles seleccionados, como Hotel Vieiras, Dos Açores, Hamburgo Palace o Rosenbrock (en Camboriú).</p>
<hr data-start=\"4550\" data-end=\"4553\">
<h3 data-start=\"4555\" data-end=\"4592\"><strong data-start=\"4559\" data-end=\"4592\">Importante – Sobre los Valores</strong></h3>
<p data-start=\"4593\" data-end=\"4913\">Los valores publicados representan siempre el <strong data-start=\"4636\" data-end=\"4684\">total del viaje según la cantidad de personas</strong> en la habitación.<br data-start=\"4695\" data-end=\"4698\">Aunque aparezca “base doble”, el sistema muestra automáticamente el <strong data-start=\"4764\" data-end=\"4797\">valor final para dos personas</strong>, o para tres personas en caso de habitación triple.<br data-start=\"4845\" data-end=\"4848\">Así, el pasajero ve el valor final sin necesidad de cálculos.</p>
<hr data-start=\"4915\" data-end=\"4918\">
<h3 data-start=\"4920\" data-end=\"4965\"><strong data-start=\"4924\" data-end=\"4965\">ITINERARIO – 10 DÍAS / 7 NOCHES (ÓMNIBUS)</strong></h3>
<p data-start=\"4967\" data-end=\"5044\"><strong data-start=\"4967\" data-end=\"4995\">Día 1 – Salida desde Córdoba</strong><br data-start=\"4995\" data-end=\"4998\">Embarque por la tarde/noche y salida rumbo a Brasil.</p>
<p data-start=\"5046\" data-end=\"5160\"><strong data-start=\"5046\" data-end=\"5088\">Día 2 – Frontera y llegada al destino</strong><br data-start=\"5088\" data-end=\"5091\">Procedimientos migratorios y continuación del viaje. Check-in en el hotel.</p>
<p data-start=\"5162\" data-end=\"5225\"><strong data-start=\"5162\" data-end=\"5186\">Día 3 – Día de playa</strong><br data-start=\"5186\" data-end=\"5189\">Tiempo libre para disfrutar de la playa.</p>
<p data-start=\"5227\" data-end=\"5308\"><strong data-start=\"5227\" data-end=\"5257\">Día 4 – Paseos opcionales</strong><br data-start=\"5257\" data-end=\"5260\">Teleférico, barco, city tour o playas cercanas.</p>
<p data-start=\"5310\" data-end=\"5364\"><strong data-start=\"5310\" data-end=\"5331\">Día 5 – Día libre</strong><br data-start=\"5331\" data-end=\"5334\">Playa o excursiones adicionales.</p>
<p data-start=\"5366\" data-end=\"5449\"><strong data-start=\"5366\" data-end=\"5398\">Día 6 – Actividades sugeridas</strong><br data-start=\"5398\" data-end=\"5401\">Centro, compras, gastronomía o atracciones locales.</p>
<p data-start=\"5451\" data-end=\"5512\"><strong data-start=\"5451\" data-end=\"5473\">Día 7 – Más playa</strong><br data-start=\"5473\" data-end=\"5476\">Día libre para disfrutar del destino.</p>
<p data-start=\"5514\" data-end=\"5591\"><strong data-start=\"5514\" data-end=\"5545\">Día 8 – Último día de playa</strong><br data-start=\"5545\" data-end=\"5548\">Aprovechamiento del hotel y la región. Pernocte.</p>
<p data-start=\"5593\" data-end=\"5670\"><strong data-start=\"5593\" data-end=\"5624\">Día 9 – Check-out y retorno</strong><br data-start=\"5624\" data-end=\"5627\">Salida por la mañana e inicio del viaje de regreso.</p>
<p data-start=\"5672\" data-end=\"5735\"><strong data-start=\"5672\" data-end=\"5715\">Día 10 – Llegada a Rosario/Buenos Aires</strong><br data-start=\"5715\" data-end=\"5718\">Fin de los servicios.</p>','1','2021-10-20 16:25:47.706399','<p>Balneário Camboriú, conocida como la “Dubái brasileña”, es un destino moderno y sofisticado en el litoral de Santa Catarina. Su skyline frente al mar y su energía cosmopolita la convierten en uno de los lugares más visitados del sur de Brasil.</p>','<p data-start=\"937\" data-end=\"1092\"><strong data-start=\"937\" data-end=\"963\">Condición para menores:</strong> hasta 2 años sin cargo y sin servicio. Pagan únicamente asistencia médica de USD 25 neto. A partir de los 3 años paga como adulto.</p> <p data-start=\"1094\" data-end=\"1347\">Los menores solo pueden embarcar con la documentación adecuada del responsable o tutor, sin ninguna excepción. El operador no se responsabiliza por el paso en la frontera ni por documentación vencida o que no cumpla con las exigencias del personal fronterizo.</p> <p data-start=\"1349\" data-end=\"1450\"><strong data-start=\"1349\" data-end=\"1370\">Tarifa por habitación</strong> (no por persona), sujeta a modificación sin previo aviso al momento de la reserva.</p> <p data-start=\"1452\" data-end=\"1643\">Recordá llevar toda la documentación necesaria para evitar inconvenientes en Migraciones. En caso de dudas, consultá el sitio oficial de Migraciones en <a class=\"decorated-link cursor-pointer\" target=\"_new\" rel=\"noopener\" data-start=\"1598\" data-end=\"1620\">www.migraciones.gob.ar</a> para más información.</p>','<p>RG, CPF ou Passaporte</p>','0','0','37',NULL,'1','42','33','1','Córdoba → Balneário Camboriú','Córdoba → Balneário Camboriú','Córdoba → Balneário Camboriú','<p data-start=\"381\" data-end=\"614\">Balneário Camboriú is one of the most popular destinations in southern Brazil. With strong European influence and modern tourist infrastructure, it blends beaches, gastronomy, attractions and entertainment in a vibrant urban setting.</p>
<p data-start=\"616\" data-end=\"779\">Its beaches offer options for every traveler: from lively Praia Central to quiet hideaways like Estaleirinho or Laranjeiras, accessible by the Unipraias cable car.</p>
<p data-start=\"781\" data-end=\"1030\">Top attractions include the Pirate Ship, Cristo Luz, the Automobile Museum and several natural viewpoints. The local cuisine mixes international flavors with fresh seafood, and nightlife is also a highlight with renowned bars, restaurants and clubs.</p>
<p data-start=\"1032\" data-end=\"1113\">Ideal for families, couples and groups of friends seeking beach, comfort and fun.</p>
<hr data-start=\"1115\" data-end=\"1118\">
<h3 data-start=\"1120\" data-end=\"1155\"><strong data-start=\"1124\" data-end=\"1155\">General Service Description</strong></h3>
<p data-start=\"1156\" data-end=\"1362\">Our services depart by tourist coach from Córdoba to Camboriú, Florianópolis or Torres. The buses are comfortable, air-conditioned, with reclining seats and coordinated assistance throughout the group trip.</p>
<p data-start=\"1364\" data-end=\"1657\">The route includes boarding points along the highway, allowing passengers to join from different towns. Once in Brazil, the service arrives directly at the assigned hotels, such as Hotel Vieiras, Dos Açores, Hamburgo Palace or Rosenbrock (in Camboriú), ensuring a smooth and organized arrival.</p>
<hr data-start=\"1659\" data-end=\"1662\">
